write(P/'budget-report.json',{'measured_at':now(),'unique_bytes_at_packaging':sum(unique.values()),'unique_blobs':len(unique),'all_new_source_and_raw_file_bytes_including_duplicates':sum(p.stat().st_size for p in allfiles),'hard_unique_budget_bytes':60000000,'margin_bytes':60000000-sum(unique.values()),'method':'SHA256 content deduplication across complete repair production and new raw evidence roots; no evidence deleted, no ZIP created.'})
